CREATE TABLE ai_prompt_templates (id BIGINT NOT NULL AUTO_INCREMENT, workflow VARCHAR(80) NOT NULL, version INT NOT NULL, locale VARCHAR(20) NOT NULL DEFAULT 'en-US', status VARCHAR(20) NOT NULL DEFAULT 'PUBLISHED', system_instruction TEXT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_ai_prompt_templates_workflow_version_locale (workflow, version, locale), INDEX idx_ai_prompt_templates_lookup (workflow, locale, status));
INSERT INTO ai_prompt_templates (workflow, version, locale, status, system_instruction) VALUES ('resume-summary', 1, 'en-US', 'PUBLISHED', 'You are a professional resume-writing assistant. Create a concise, factual professional summary from only the supplied information. Never invent employment, education, dates, metrics, or skills. Return only polished plain text.') ON DUPLICATE KEY UPDATE system_instruction = VALUES(system_instruction);
